@bot.tree.command(name="gamecard", description="The live score card for any game the group has legs on")
@app_commands.guild_only()
@app_commands.describe(game="Pick a game (live games first). Leave empty for the game that's on right now")
@app_commands.autocomplete(game=gamecard_autocomplete)
async def gamecard_cmd(interaction: discord.Interaction, game: Optional[str] = None):
    await interaction.response.defer(thinking=True)
    try:
        embed, f = await gamecard_payload(interaction.client, interaction.guild_id, interaction.user.id, game)
    except Exception:
        log.exception("Game card failed")
        await interaction.followup.send("I couldn't draw that card just now. Try again in a minute.", ephemeral=True)
        return
    if f is None:
        await interaction.followup.send(embed, ephemeral=True)
        return
    await interaction.followup.send(embed=embed, file=f, allowed_mentions=discord.AllowedMentions.none())


# ---- r26: /admin askchannel ------------------------------------------------------------------------------------

@admin_group.command(name="askchannel", description="Make a channel where anything typed is a question for the bot (+ news)")
@app_commands.describe(turn_off="Turn the ask channel off")
@sec_admin_only
async def admin_askchannel(interaction: discord.Interaction, turn_off: bool = False):
    gid = interaction.guild_id
    if turn_off:
        set_setting(gid, "ask_channel", None)
        await interaction.response.send_message("The ask channel is off. @mention me anywhere to ask a question.",
                                                ephemeral=True)
        return
    set_setting(gid, "ask_channel", str(interaction.channel_id))
    note = "" if ask_enabled() else ("\n⚠️ Answers need a free `GROQ_API_KEY` or `GEMINI_API_KEY` on Railway. "
                                      "The news feed and slip breakdowns work without one.")
    await interaction.response.send_message(
        "💬 **This is now the ask channel.** Anything typed here is a question for me, no @mention needed. "
        "Screenshots here get a breakdown and are never logged.\n"
        "📰 I'll also post news here: players on the group's open slips landing on or coming off the injury report, "
        "and 🔁 reboots when a player doesn't play. (Switch the news off in `/admin panel`.)" + note,
        allowed_mentions=discord.AllowedMentions.none())
    try:
        await audit(interaction.client, gid, f"{interaction.user.display_name} made <#{interaction.channel_id}> the ask channel")
    except Exception:
        pass


@bot.tree.error
async def on_app_command_error(interaction: discord.Interaction,
                               error: app_commands.AppCommandError):
    log.exception("Command failed", exc_info=error)
    original = getattr(error, "original", error)
    if isinstance(original, discord.Forbidden):
        msg = ("I don't have permission to do that here. Check that my role can **View Channel**, "
               "**Send Messages**, **Embed Links** and **Attach Files** in this channel "
               "(Edit Channel → Permissions → add PIMP-BOT).")
    else:
        msg = "Something went wrong running that. Check the bot's logs for details."
    try:
        if interaction.response.is_done():
            await interaction.followup.send(msg, ephemeral=True)
        else:
            await interaction.response.send_message(msg, ephemeral=True)
    except Exception:
        log.info("Couldn't tell the user the command failed (the interaction expired)")


if __name__ == "__main__":
    if not TOKEN:
        raise SystemExit("DISCORD_TOKEN is missing. Add it as a variable on Railway "
                         "(or in .env when running locally).")
    logging.basicConfig(level=logging.INFO, format="%(asctime)s %(levelname)s %(message)s")
    bot.run(TOKEN, log_handler=None)
